package fr.bbodin.courbedepoids;
import android.app.AlertDialog;import android.app.DatePickerDialog;import android.app.TimePickerDialog;import android.app.Fragment;import android.os.Bundle;import android.graphics.Color;import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.widget.LinearLayout;import android.widget.TextView;import android.widget.Toast;import java.text.SimpleDateFormat;import java.util.Calendar;import java.util.Locale;import java.util.List;import java.util.Map;import java.util.LinkedHashMap;import org.json.JSONObject;
public class AddMeasurementFragment extends Fragment{
 private TextView dateInput,timeInput;private LinearLayout typesContainer;private final Calendar date=Calendar.getInstance();
 @Override public View onCreateView(LayoutInflater i,ViewGroup c,Bundle b){return i.inflate(R.layout.activity_add_measurement,c,false);}
 @Override public void onViewCreated(View v,Bundle b){super.onViewCreated(v,b);dateInput=v.findViewById(R.id.date_input);timeInput=v.findViewById(R.id.time_input);typesContainer=v.findViewById(R.id.generic_types_container);updateDate();updateTime();dateInput.setOnClickListener(x->openDatePicker());timeInput.setOnClickListener(x->openTimePicker());addConfiguredTypes();}
 private void addConfiguredTypes(){List<JSONObject> types=new LoggingTypeRegistry(getActivity()).getTypes();Map<String,List<JSONObject>> categories=new LinkedHashMap<>();for(JSONObject t:types){String c=t.optString("category","other");if(!categories.containsKey(c))categories.put(c,new java.util.ArrayList<>());categories.get(c).add(t);}for(Map.Entry<String,List<JSONObject>> category:categories.entrySet()){TextView heading=new TextView(getActivity());heading.setText(categoryLabel(category.getKey()));heading.setTextColor(Color.rgb(71,85,105));heading.setTextSize(13);heading.setTypeface(null,android.graphics.Typeface.BOLD);heading.setPadding(dp(4),dp(12),dp(4),dp(4));typesContainer.addView(heading);android.widget.HorizontalScrollView scroll=new android.widget.HorizontalScrollView(getActivity());scroll.setHorizontalScrollBarEnabled(false);LinearLayout choices=new LinearLayout(getActivity());choices.setOrientation(LinearLayout.HORIZONTAL);for(JSONObject type:category.getValue()){LinearLayout item=new LinearLayout(getActivity());item.setGravity(android.view.Gravity.CENTER);item.setPadding(dp(14),0,dp(14),0);item.setBackgroundResource(R.drawable.bg_input);item.setClickable(true);item.setFocusable(true);TextView label=new TextView(getActivity());label.setText(type.optString("icon","•")+" "+type.optString("label"));label.setTextColor(Color.rgb(20,36,58));item.addView(label);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(50));p.setMargins(dp(4),dp(4),dp(4),dp(4));choices.addView(item,p);item.setOnClickListener(x->showConfiguredForm(type));}scroll.addView(choices);typesContainer.addView(scroll);}}
 private String categoryLabel(String c){if("body".equals(c))return "Corps";if("health".equals(c))return "Santé";if("nutrition".equals(c))return "Nutrition";if("activity".equals(c))return "Activité";return c;}
 private void showConfiguredForm(JSONObject type){ConfiguredLoggingForm form=new ConfiguredLoggingForm(getActivity(),type,null);Calendar selected=(Calendar)date.clone();new AlertDialog.Builder(getActivity()).setTitle(type.optString("icon","")+" "+type.optString("label")).setView(form.getView()).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",(d,w)->{try{JSONObject payload=form.readPayload();new WeightDatabase(getActivity()).saveGenericEvent(type.optString("id"),new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(selected.getTime()),selected.getTimeInMillis(),payload.toString());Toast.makeText(getActivity(),type.optString("label")+" enregistré.",Toast.LENGTH_SHORT).show();((MainActivity)getActivity()).showTab(0);}catch(Exception e){Toast.makeText(getActivity(),e.getMessage()==null?"Données invalides":e.getMessage(),Toast.LENGTH_LONG).show();}}).show();}
 private void openDatePicker(){new DatePickerDialog(getActivity(),(p,y,m,d)->{int h=date.get(Calendar.HOUR_OF_DAY),n=date.get(Calendar.MINUTE);date.set(y,m,d,h,n,0);date.set(Calendar.MILLISECOND,0);updateDate();},date.get(Calendar.YEAR),date.get(Calendar.MONTH),date.get(Calendar.DAY_OF_MONTH)).show();}
 private void openTimePicker(){new TimePickerDialog(getActivity(),(p,h,m)->{date.set(Calendar.HOUR_OF_DAY,h);date.set(Calendar.MINUTE,m);date.set(Calendar.SECOND,0);date.set(Calendar.MILLISECOND,0);updateTime();},date.get(Calendar.HOUR_OF_DAY),date.get(Calendar.MINUTE),true).show();}
 private void updateTime(){timeInput.setText("Heure de mesure · "+new SimpleDateFormat("HH:mm",Locale.FRANCE).format(date.getTime())+" ("+java.util.TimeZone.getDefault().getID()+")");}
 private void updateDate(){Calendar s=(Calendar)date.clone();s.set(Calendar.HOUR_OF_DAY,0);s.set(Calendar.MINUTE,0);s.set(Calendar.SECOND,0);s.set(Calendar.MILLISECOND,0);Calendar today=Calendar.getInstance();today.set(Calendar.HOUR_OF_DAY,0);today.set(Calendar.MINUTE,0);today.set(Calendar.SECOND,0);today.set(Calendar.MILLISECOND,0);String label;if(s.getTimeInMillis()==today.getTimeInMillis())label="Aujourd'hui";else{Calendar y=(Calendar)today.clone();y.add(Calendar.DAY_OF_YEAR,-1);Calendar t=(Calendar)today.clone();t.add(Calendar.DAY_OF_YEAR,1);if(s.getTimeInMillis()==y.getTimeInMillis())label="Hier";else if(s.getTimeInMillis()==t.getTimeInMillis())label="Demain";else label=new SimpleDateFormat("EEEE d MMMM yyyy",Locale.FRANCE).format(date.getTime());}dateInput.setText(label);}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
}
